            var walls=new RoadGeometry();foreach(var ring in data.outerPavingRings)for(int i=0;i<ring.points.Length-1;i++){var a=ring.points[i];var b=ring.points[i+1];int steps=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(a,b)/.5f));for(int j=0;j<steps;j++){var x=Vector3.Lerp(a,b,(float)j/steps);var z=Vector3.Lerp(a,b,(float)(j+1)/steps);x.y=z.y=data.curbTopY;walls.Wall(x,z,PlanningGround(lands,x.x,x.z)-.025f,PlanningGround(lands,z.x,z.z)-.025f);}}var wallOwner=root.Find("ContinuousSurfaces/Unified_OuterRoadbed");CopyUpdatedMesh(wallOwner,WallMesh(walls,wallOwner,"Unified_OuterRoadbed"));
