        var actualSurfaces=new List<UnifiedSurface>();foreach(var expected in data.surfaces){var owner=SurfaceOwner(expected,root,all);var mesh=owner.GetComponent<MeshFilter>().sharedMesh;var vertices=mesh.vertices.Select(owner.TransformPoint).ToArray();if(vertices.Length!=expected.vertices.Length)failures.Add("Vertex count: "+expected.name);for(int i=0;i<Mathf.Min(vertices.Length,expected.vertices.Length);i++){var target=expected.vertices[i];target.y=UnifiedY(expected.kind,data);result.maxVertexError=Mathf.Max(result.maxVertexError,Vector3.Distance(vertices[i],target));result.maxTopHeightError=Mathf.Max(result.maxTopHeightError,Mathf.Abs(vertices[i].y-target.y));}actualSurfaces.Add(new UnifiedSurface{name=expected.name,kind=expected.kind,nativeOwner=expected.nativeOwner,vertices=vertices,triangles=mesh.triangles});}
