            foreach(var hit in Physics.OverlapBox(new Vector3(point.x,data.asphaltY+1.2f,point.z),new Vector3(.95f,1,1.95f),Quaternion.LookRotation(direction),~((1<<4)|(1<<13)|(1<<11)),QueryTriggerInteraction.Ignore)){if(hit is TerrainCollider)continue;obstacles.Add(new RoadObstacle{road=line.id,collider=P(hit.transform),sample=point,lane=lane});}}}
        result.obstacles=obstacles.ToArray();var avenue=data.plan.roads.Single(r=>r.id=="MarketAvenue");result.throughMarketAvenue=true;for(float z=avenue.a.z;z<=avenue.b.z;z+=.5f)if(!Physics.RaycastAll(new Vector3(avenue.a.x,4,z),Vector3.down,2,~0,QueryTriggerInteraction.Ignore).Any(h=>h.collider.name=="Unified_Carriageway"))result.throughMarketAvenue=false;
